INSERT INTO _migration_439_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_biotech_s1_001', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which enzyme cuts DNA at specific recognition sequences during genetic engineering?', 'multiple_choice', NULL, '["A. DNA ligase","B. DNA polymerase","C. Restriction endonuclease","D. Reverse transcriptase"]', 'C', 'Restriction endonucleases recognise short, specific base sequences and cut the DNA backbone there, often leaving sticky ends. DNA ligase joins fragments together, DNA polymerase synthesises new strands, and reverse transcriptase makes DNA from an RNA template. Therefore the correct answer is C: Restriction endonuclease.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biotech_s1_002', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'What does the abbreviation PCR stand for?', 'multiple_choice', NULL, '["A. Protein chain replication","B. Polymerase copying of RNA","C. Primer-controlled replication","D. Polymerase chain reaction"]', 'D', 'PCR, the polymerase chain reaction, amplifies a chosen region of DNA exponentially through repeated cycles of denaturation, primer annealing and extension by a thermostable DNA polymerase such as Taq polymerase. Therefore the correct answer is D: Polymerase chain reaction.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biotech_s1_003', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In PCR, why is the extension step carried out at about 72 °C?', 'multiple_choice', NULL, '["A. Taq DNA polymerase is thermostable and works close to its optimum temperature at 72 °C","B. 72 °C is needed to separate the two DNA strands","C. Primers can only anneal to the template at 72 °C","D. The DNA template denatures completely at 72 °C"]', 'A', 'Taq polymerase, isolated from the thermophilic bacterium Thermus aquaticus, survives the roughly 95 °C denaturation step and extends primers fastest near its optimum of about 72 °C. Strands separate at about 95 °C and primers anneal at about 55 °C. Therefore the correct answer is A: Taq DNA polymerase is thermostable and works close to its optimum temperature at 72 °C.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_biotech_s1_004', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which vector is commonly used to transfer genes into plant cells?', 'multiple_choice', NULL, '["A. The protein coat of a bacteriophage","B. The Ti plasmid of Agrobacterium tumefaciens","C. Ribosomes from the host plant","D. Plasmids isolated from human gut bacteria"]', 'B', 'Agrobacterium tumefaciens naturally transfers part of its Ti (tumour-inducing) plasmid, the T-DNA, into plant cells, where it integrates into the plant genome. Replacing the tumour-causing genes with a desired gene turns the Ti plasmid into a plant transformation vector. Therefore the correct answer is B: The Ti plasmid of Agrobacterium tumefaciens.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biotech_s1_005', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Bacteria containing an inserted human insulin gene produce functional human insulin. Which feature of the genetic code makes this possible?', 'multiple_choice', NULL, '["A. Bacteria are able to read the code backwards","B. Human genes contain bacterial promoter sequences","C. The genetic code is universal — the same codons specify the same amino acids in bacteria and humans","D. Insulin is not made of amino acids"]', 'C', 'Because the genetic code is (almost) universal, a bacterial ribosome translates human mRNA codons into exactly the same amino acid sequence as a human cell would, so the protein produced by the engineered bacteria is genuine human insulin. Therefore the correct answer is C: The genetic code is universal — the same codons specify the same amino acids in bacteria and humans.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_cambridge'),
('q_albio_biotech_s1_006', 'topic_alevel_bio_biotech', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student outlines how bacteria are genetically engineered to produce human insulin.', 'structured', NULL, NULL, '(a) Reverse transcriptase synthesises a complementary DNA (cDNA) copy of the insulin gene from the mature mRNA extracted from pancreatic beta cells; this cDNA contains the coding sequence without introns, which bacteria cannot remove. (b) DNA ligase joins the sugar–phosphate backbones of the insulin gene and the cut plasmid by catalysing the formation of phosphodiester bonds between their complementary sticky ends, sealing the gene into the plasmid to make recombinant DNA. (c) Any one developed point, for example: the product is exact human insulin, so it is less likely to trigger an immune response than pig or cow insulin; or GM bacteria grow rapidly in fermenters, giving large, reliable and cheaper supplies without the use of animals.', '(a) Reverse transcriptase synthesises a complementary DNA (cDNA) copy of the insulin gene from the mature mRNA extracted from pancreatic beta cells; this cDNA contains the coding sequence without introns, which bacteria cannot remove. (b) DNA ligase joins the sugar–phosphate backbones of the insulin gene and the cut plasmid by catalysing the formation of phosphodiester bonds between their complementary sticky ends, sealing the gene into the plasmid to make recombinant DNA. (c) Any one developed point, for example: the product is exact human insulin, so it is less likely to trigger an immune response than pig or cow insulin; or GM bacteria grow rapidly in fermenters, giving large, reliable and cheaper supplies without the use of animals.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_439_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_albio_biotech_s1_006_a', 'q_albio_biotech_s1_006', 'a', 'State the role of reverse transcriptase in obtaining the human insulin gene.', '2', 'Reverse transcriptase synthesises a complementary DNA (cDNA) copy of the insulin gene from the mature mRNA extracted from pancreatic beta cells; this cDNA contains the coding sequence without introns, which bacteria cannot remove.', '1'),
('sqp_q_albio_biotech_s1_006_b', 'q_albio_biotech_s1_006', 'b', 'Describe the role of DNA ligase in forming a recombinant plasmid.', '2', 'DNA ligase joins the sugar–phosphate backbones of the insulin gene and the cut plasmid by catalysing the formation of phosphodiester bonds between their complementary sticky ends, sealing the gene into the plasmid to make recombinant DNA.', '2'),
('sqp_q_albio_biotech_s1_006_c', 'q_albio_biotech_s1_006', 'c', 'Explain one advantage of producing insulin from genetically modified bacteria rather than extracting it from animal pancreases.', '2', 'Any one developed point, for example: the product is exact human insulin, so it is less likely to trigger an immune response than pig or cow insulin; or GM bacteria grow rapidly in fermenters, giving large, reliable and cheaper supplies without the use of animals.', '3');
INSERT INTO _migration_439_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_439_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_439_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_439_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_439_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_439_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint1-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_439_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_439_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_439_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_439_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_439_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_439_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
